import {
  MjmlColumn,
  MjmlDivider,
  MjmlImage,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  Mjml,
  MjmlBody,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlStyle,
  MjmlTable,
  MjmlWrapper,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

type ReviewsVariant =
  | "with-divider"
  | "simple"
  | "divider-top"
  | "with-logo"
  | "logo-split"
  | "logo-bottom"
  | "avatar-inline"
  | "avatar-inline-split"
  | "avatar-inline-bottom"
  | "centered-with-avatar"
  | "centered-avatar-split"
  | "centered-avatar-bottom"
  | "avatar-logo"
  | "avatar-logo-split"
  | "avatar-logo-bottom";

type FullWidthReviewsVariant =
  | ReviewsVariant
  | "avatar-aside"
  | "avatar-aside-split"
  | "avatar-aside-reverse";

interface InternalReviewItem {
  avatarUrl?: string;
  company?: string;
  date: string;
  logoAlt?: string;
  logoUrl?: string;
  logoWidth?: number;
  name: string;
  rating: number;
  text: string;
}

type ReviewsLayout = "full-width" | "masonry-grid" | "two-columns";
const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const reviewsResponsiveStyles = "";

const defaultReviews: InternalReviewItem[] = [
  {
    avatarUrl: emailAsset(`reviews/avatar.jpg`),
    company: "Monarch",
    date: "August 16, 2025",
    logoAlt: "Monarch",
    logoUrl: emailAsset(`reviews/logo-monarch.png`),
    logoWidth: 145,
    name: "Jenna Hendricks",
    rating: 4.5,
    text: "This tool made it incredibly easy to launch polished projects. The components are flexible, clean, and work perfectly across platforms.",
  },
  {
    avatarUrl: emailAsset(`reviews/avatar-3.jpg`),
    company: "Accentic",
    date: "October 7, 2025",
    logoAlt: "Accentic",
    logoUrl: emailAsset(`reviews/logo-accentic.png`),
    logoWidth: 165,
    name: "Ella James",
    rating: 4.5,
    text: "Great set of templates. I saved hours of dev time and everything came out looking professional and well executed, even in tricky environments.",
  },
  {
    avatarUrl: emailAsset(`reviews/avatar-4.jpg`),
    company: "Amada",
    date: "June 2, 2025",
    logoAlt: "Amada",
    logoUrl: emailAsset(`reviews/logo-amada.png`),
    logoWidth: 137,
    name: "Roderick Adams",
    rating: 3.5,
    text: "Super impressed with the quality. The designs are modern, easy to adapt, and helped streamline our entire workflow. Highly recommended!",
  },
];

const twoColumnReviews: InternalReviewItem[] = [
  defaultReviews[0],
  {
    ...defaultReviews[1],
    avatarUrl: emailAsset(`reviews/avatar-2.jpg`),
    date: "October 9, 2025",
    name: "Adam Johnson",
    rating: 5,
  },
];

const Rating = ({
  centered,
  rating,
  size,
}: {
  centered: boolean;
  rating: number;
  size: 16 | 24;
}) => {
  const getIcon = (index: number) => {
    if (rating >= index + 1) {
      return "solid";
    }
    if (rating >= index + 0.5) {
      return "half";
    }
    return "outline";
  };

  return (
    <MjmlTable
      align={centered ? "center" : "left"}
      cellpadding="0"
      cellspacing="0"
      padding="0"
      role="presentation"
      width={`${size * 5 + 16}px`}
    >
      <tbody>
        <tr>
          {[0, 1, 2, 3, 4].map((index) => (
            <td
              key={index}
              style={{
                paddingRight: index === 4 ? "0" : "4px",
                width: `${size}px`,
              }}
            >
              <img
                alt=""
                src={emailAsset(`icon-star-${getIcon(index)}.png`)}
                style={{ display: "block" }}
                width={size}
              />
            </td>
          ))}
        </tr>
      </tbody>
    </MjmlTable>
  );
};

const ReviewCopy = ({
  centered,
  featured,
  item,
  separateAuthor,
}: {
  centered: boolean;
  featured: boolean;
  item: InternalReviewItem;
  separateAuthor?: boolean;
}) => (
  <>
    <MjmlText
      align={centered ? "center" : "left"}
      color="#4b5563"
      fontFamily={fontFamily}
      fontSize={featured ? "20px" : "16px"}
      lineHeight={featured ? "28px" : "24px"}
      padding="0"
    >
      {item.text}
    </MjmlText>
    <MjmlSpacer height="20px" />
    <MjmlText
      align={centered ? "center" : "left"}
      color="#9ca3af"
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="600"
      lineHeight="24px"
      padding="0"
    >
      {separateAuthor ? null : (
        <>
          {item.name} - {item.company}
          <br />
        </>
      )}
      {item.date}
    </MjmlText>
  </>
);

const AccentDivider = ({ centered = false }: { centered?: boolean }) => (
  <MjmlDivider
    align={centered ? "center" : "left"}
    borderColor="#6366f1"
    borderWidth="4px"
    padding="0"
    width="96px"
  />
);

const ReviewLogo = ({
  centered,
  item,
  trailingSpace = true,
}: {
  centered?: boolean;
  item: InternalReviewItem;
  trailingSpace?: boolean;
}) => (
  <>
    <MjmlImage
      align={centered ? "center" : "left"}
      alt={item.logoAlt ?? item.company ?? ""}
      padding="0"
      src={item.logoUrl}
      width={`${item.logoWidth ?? 145}px`}
    />
    {trailingSpace ? <MjmlSpacer height="24px" /> : null}
  </>
);

const ReviewAvatar = ({
  centered,
  item,
  rating,
  size,
}: {
  centered: boolean;
  item: InternalReviewItem;
  rating: number;
  size: 16 | 24;
}) => (
  <>
    <MjmlImage
      align={centered ? "center" : "left"}
      alt={item.name}
      borderRadius="9999px"
      padding="0"
      src={item.avatarUrl}
      width="64px"
    />
    <MjmlSpacer height="12px" />
    <MjmlText
      align={centered ? "center" : "left"}
      color="#030712"
      fontFamily={fontFamily}
      fontSize="16px"
      fontWeight="700"
      lineHeight="24px"
      padding="0"
    >
      {item.name}
    </MjmlText>
    <Rating centered={centered} rating={rating} size={size} />
    <MjmlSpacer height="24px" />
  </>
);

const ReviewTopIdentity = ({
  avatarAtTop,
  centered,
  item,
  logoAtTop,
  rating,
  showRatingOnly,
  size,
}: {
  avatarAtTop: boolean;
  centered: boolean;
  item: InternalReviewItem;
  logoAtTop: boolean;
  rating: number;
  showRatingOnly: boolean;
  size: 16 | 24;
}) => {
  if (logoAtTop) {
    return (
      <>
        <ReviewLogo centered={centered} item={item} trailingSpace={false} />
        <MjmlSpacer height="36px" />
        <Rating centered={centered} rating={rating} size={size} />
        <MjmlSpacer height="36px" />
      </>
    );
  }
  if (avatarAtTop) {
    return (
      <ReviewAvatar
        centered={centered}
        item={item}
        rating={rating}
        size={size}
      />
    );
  }
  if (showRatingOnly) {
    return (
      <>
        <Rating centered={centered} rating={rating} size={size} />
        <MjmlSpacer height="36px" />
      </>
    );
  }
  return null;
};

const ReviewBottomIdentity = ({
  avatarAtBottom,
  item,
  logoAtBottom,
  rating,
  size,
}: {
  avatarAtBottom: boolean;
  item: InternalReviewItem;
  logoAtBottom: boolean;
  rating: number;
  size: 16 | 24;
}) => {
  if (logoAtBottom) {
    return (
      <>
        <MjmlSpacer height="36px" />
        <ReviewLogo item={item} trailingSpace={false} />
      </>
    );
  }
  if (avatarAtBottom) {
    return (
      <>
        <MjmlSpacer height="36px" />
        <MjmlImage
          alt={item.name}
          borderRadius="9999px"
          padding="0"
          src={item.avatarUrl}
          width="64px"
        />
        <MjmlSpacer height="12px" />
        <Rating centered rating={rating} size={size} />
      </>
    );
  }
  return null;
};

const ReviewContent = ({
  featured,
  item,
  layout,
  variant,
}: {
  featured: boolean;
  item: InternalReviewItem;
  layout: ReviewsLayout;
  variant: FullWidthReviewsVariant;
}) => {
  const centered =
    variant.startsWith("centered") || variant.startsWith("avatar-logo");
  const hasAvatar =
    variant.startsWith("avatar") || variant.startsWith("centered");
  const hasLogo = variant.includes("logo");
  const dividerTop =
    variant === "divider-top" ||
    variant.endsWith("-bottom") ||
    variant.endsWith("-reverse");
  const dividerMiddle =
    variant === "with-divider" || variant.endsWith("-split");
  const identityAtBottom = variant.endsWith("-bottom");
  const logoAtTop = hasLogo && !identityAtBottom;
  const avatarAtTop = hasAvatar && !identityAtBottom;
  const showRatingOnly = !hasLogo && !avatarAtTop;
  const { rating } = item;
  const size = layout === "full-width" ? 16 : 24;

  if (!hasAvatar && !hasLogo) {
    if (variant === "divider-top") {
      return (
        <>
          <AccentDivider centered={centered} />
          <MjmlSpacer height="24px" />
          <ReviewCopy centered={centered} featured={featured} item={item} />
          <MjmlSpacer height="36px" />
          <Rating centered={centered} rating={rating} size={size} />
        </>
      );
    }
    return (
      <>
        <Rating centered={centered} rating={rating} size={size} />
        <MjmlSpacer height="36px" />
        {variant === "with-divider" ? (
          <>
            <AccentDivider centered={centered} />
            <MjmlSpacer height="24px" />
          </>
        ) : null}
        <ReviewCopy centered={centered} featured={featured} item={item} />
      </>
    );
  }

  return (
    <>
      {dividerTop ? (
        <>
          <AccentDivider centered={centered} />
          <MjmlSpacer height="24px" />
        </>
      ) : null}
      <ReviewTopIdentity
        avatarAtTop={avatarAtTop}
        centered={centered}
        item={item}
        logoAtTop={logoAtTop}
        rating={rating}
        showRatingOnly={showRatingOnly}
        size={size}
      />
      {dividerMiddle ? (
        <>
          <AccentDivider centered={centered} />
          <MjmlSpacer height="24px" />
        </>
      ) : null}
      <ReviewCopy
        centered={centered}
        featured={featured}
        item={item}
        separateAuthor={hasAvatar}
      />
      <ReviewBottomIdentity
        avatarAtBottom={hasAvatar && identityAtBottom}
        item={item}
        logoAtBottom={hasLogo && identityAtBottom}
        rating={rating}
        size={size}
      />
    </>
  );
};

const ReviewColumn = ({
  featured,
  item,
  layout,
  variant,
  width,
}: {
  featured: boolean;
  item: InternalReviewItem;
  layout: ReviewsLayout;
  variant: FullWidthReviewsVariant;
  width: string;
}) => (
  <MjmlColumn padding="0" verticalAlign="top" width={width}>
    <ReviewContent
      featured={featured}
      item={item}
      layout={layout}
      variant={variant}
    />
  </MjmlColumn>
);

const ReviewsSection = ({
  layout,
  reviews,
  variant = "with-divider",
}: {
  layout: ReviewsLayout;
  reviews?: InternalReviewItem[];
  variant?: FullWidthReviewsVariant;
}) => {
  const items =
    reviews ?? (layout === "two-columns" ? twoColumnReviews : defaultReviews);
  if (layout === "full-width") {
    return (
      <MjmlSection backgroundColor="#fffffe" padding="44px 24px">
        <ReviewColumn
          featured
          item={items[0]}
          layout={layout}
          variant={variant}
          width="552px"
        />
      </MjmlSection>
    );
  }
  if (layout === "masonry-grid") {
    return (
      <>
        <MjmlSection backgroundColor="#fffffe" padding="44px 24px 0">
          <ReviewColumn
            featured
            item={items[0]}
            layout={layout}
            variant={variant}
            width="552px"
          />
        </MjmlSection>
        <MjmlSection backgroundColor="#fffffe" padding="64px 24px 44px">
          <ReviewColumn
            featured={false}
            item={items[1]}
            layout={layout}
            variant={variant}
            width="254px"
          />
          <MjmlColumn padding="0" width="44px" />
          <ReviewColumn
            featured={false}
            item={items[2]}
            layout={layout}
            variant={variant}
            width="254px"
          />
        </MjmlSection>
      </>
    );
  }
  return (
    <MjmlSection backgroundColor="#fffffe" padding="44px 24px">
      <ReviewColumn
        featured={false}
        item={items[0]}
        layout={layout}
        variant={variant}
        width="254px"
      />
      <MjmlColumn padding="0" width="44px" />
      <ReviewColumn
        featured={false}
        item={items[1]}
        layout={layout}
        variant={variant}
        width="254px"
      />
    </MjmlSection>
  );
};

interface FullWidthReviews_FullWidthReviewsProps {
  reviews?: ReviewItem[];
  theme?: EmailTheme;
  variant?: FullWidthReviewsVariant;
}

const FullWidthReviews_FullWidthReviewsSection = ({
  reviews,
  variant = "with-divider",
}: Omit<FullWidthReviews_FullWidthReviewsProps, "theme">) => (
  <ReviewsSection layout="full-width" reviews={reviews} variant={variant} />
);

const FullWidthReviews_FullWidthReviews = ({
  theme = defaultTheme,
  ...props
}: FullWidthReviews_FullWidthReviewsProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Customer review</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
      <MjmlStyle>{reviewsResponsiveStyles}</MjmlStyle>
    </MjmlHead>
    <MjmlBody backgroundColor="#f1f5f9" width={theme.containerWidth}>
      <MjmlWrapper padding="0">
        <FullWidthReviews_FullWidthReviewsSection {...props} />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

FullWidthReviews_FullWidthReviews.PreviewProps = {
  theme: defaultTheme,
  variant: "with-divider",
} satisfies FullWidthReviews_FullWidthReviewsProps;

const __FullWidthReviews = FullWidthReviews_FullWidthReviews;

interface MasonryReviews_MasonryGridReviewsProps {
  reviews?: ReviewItem[];
  theme?: EmailTheme;
  variant?: ReviewsVariant;
}

const MasonryReviews_MasonryGridReviewsSection = ({
  reviews,
  variant = "with-divider",
